#include <iostream>
#include <string>

struct ExpensiveObject {
  std::string data; // Simulates expensive data
  ExpensiveObject(const std::string& d) : data(d) { std::cout << "ExpensiveObject constructed\n"; }
  ExpensiveObject(const ExpensiveObject& other) : data(other.data) { std::cout << "ExpensiveObject copy-constructed\n"; }
  ExpensiveObject(ExpensiveObject&& other) noexcept : data(std::move(other.data)) { std::cout << "ExpensiveObject move-constructed\n"; }
  ~ExpensiveObject() { std::cout << "ExpensiveObject destructed\n"; }
};

ExpensiveObject createExpensiveObject(const std::string& s) {
  return ExpensiveObject(s);
}

int main() {
  ExpensiveObject obj = createExpensiveObject("Hello");
  return 0;
}
